def tri(n):
    def tribonacci_helper(x):
        if x == 1:
            return 3
        elif x % 2 == 0:
            return 1 + x // 2
        else:
            return tribonacci_helper(x - 1) + tribonacci_helper(x - 2) + tribonacci_helper(x + 1)

    result = [tribonacci_helper(i) for i in range(n + 1)]
    return result
```

