from heapq import heappush, heappop

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Priority queue to store (path, current_value, current_position)
    pq = []
    for i in range(N):
        for j in range(N):
            heappush(pq, ([grid[i][j]], grid[i][j], (i, j)))

    while pq:
        path, current_value, (x, y) = heappop(pq)

        if len(path) == k:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                new_path = path + [grid[nx][ny]]
                heappush(pq, (new_path, grid[nx][ny], (nx, ny)))

    return []
```

